package net.civeira.phylax.feature.observe.source.sync;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServer;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerCreateEvent;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerDeleteEvent;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerDisableEvent;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerEnableEvent;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerUpdateEvent;
import net.civeira.phylax.feature.observe.source.ObservedSourceSyncService;
import net.civeira.phylax.feature.observe.source.OriginRef;

/**
 * Keeps the observed-source of each resource server in sync with its domain events.
 *
 * Generated by the trait observable from the model (entity resource-server, key code, label code).
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ResourceServerObservedSourceSync {

  private final ObservedSourceSyncService sync;

  void onCreate(@Observes final ResourceServerCreateEvent event) {
    sync.upsert(ResourceServerObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onUpdate(@Observes final ResourceServerUpdateEvent event) {
    sync.upsert(ResourceServerObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onEnable(@Observes final ResourceServerEnableEvent event) {
    sync.upsert(ResourceServerObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onDisable(@Observes final ResourceServerDisableEvent event) {
    sync.upsert(ResourceServerObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onDelete(@Observes final ResourceServerDeleteEvent event) {
    sync.detach("api", event.getPayload().getUid());
  }

  static OriginRef toOrigin(final ResourceServer resourceServer) {
    return new OriginRef("api", resourceServer.getUid(), resourceServer.getCode(),
        resourceServer.getCode(), Boolean.TRUE.equals(resourceServer.isEnabled()));
  }
}
